-- S469 SkyLemonadeBerry, 2026-10-24. Rule 8 ingest through execute_sql: INSERT-only, new slugs dated today, author SkyLemonadeBerry-S469.
-- Rollback: supersede by slug under actor 'SkyLemonadeBerry-S469-rollback'.
insert into public.cpl_memory (slug, kind, org, title, summary, detail, plain, tags, affects, source, related, author, event_date, status, verified_by)
values
('sam-ask-sierra-library-first-bottom-right-2026-10-24', 'decision', 'cpl', 'Sam: the Ask Sierra chip and side bar go on the public library first, as one script any page can load, the chip in the bottom-right corner', 'Sam, 2026-10-24 ~20:37Z, answering S469''s two questions on his ask of ~17:10Z: pages, "Library first" (one script any page can load, added to the public library now, other pages after he has seen it there); chip spot, "Bottom-right corner" (a floating chip that stays put while scrolling). Both were the recommended choice.', 'Declined: COBI''s header link opening the bar, and every page in one PR; the chip among the header links. Other pages (COBI, the funding model page, the Fact Sheet) wait for his word after he has seen the library''s.', 'Sam chose to put the Ask Sierra button on the public library first, floating in the lower right corner.', array['sierra','library','public-library','ui','sam-ruling']::text[], array['sierra/sidebar.js','library/index.html']::text[], 'Sam in chat, S469, 2026-10-24 ~20:37Z (two picks)', array['sam-ask-sierra-chip-sidebar-2026-10-24']::text[], 'SkyLemonadeBerry-S469', '2026-10-24', 'verified', 'Sam (his picks in chat, 2026-10-24)'),
('ask-sierra-sidebar-built-2026-10-24', 'milestone', 'cpl', 'The Ask Sierra chip opens Sierra in a side bar on the public library (sierra/sidebar.js, cpl-project-tracker#2424)', 'Built by S469 under Sam''s picks: a chip in the bottom-right corner opens a side bar framing the public sierra/ page, loaded on the first open and kept while shut. From 1200px the page narrows beside her and stays in use; below, she takes the screen as a modal and the page behind is inert. Close and Escape return focus to the chip.', 'The frame takes the host''s theme in ?theme=, which her head script now reads before the stored choice, and follows a switch. A host maps the --sierra-bar-* tokens onto its own; the library does. tests/sierra_sidebar.test.js 29 checks, 15 mutations caught; a11y views public-library-sierra and -dark with keyboard checks at 1024px and 1440px. Another page joins with one script tag and a token map.', 'The public library now has an Ask Sierra button that opens Sierra beside the page.', array['sierra','library','public-library','ui','a11y']::text[], array['sierra/sidebar.js','sierra/index.html','library/index.html','tests/sierra_sidebar.test.js','a11y.config.js']::text[], 'cpl-project-tracker#2424', array['sam-ask-sierra-library-first-bottom-right-2026-10-24','sam-ask-sierra-chip-sidebar-2026-10-24']::text[], 'SkyLemonadeBerry-S469', '2026-10-24', 'proposed', null),
('pitfall-framed-page-keys-and-theme-2026-10-24', 'pitfall', 'cpl', 'A page framed in a side bar keeps its own keys and its own theme rule: Escape in the frame never reaches the host, and a device-following page paints dark beside a Light host', 'S469, 2026-10-24: keydown inside a same-origin iframe does not bubble to the host document, so the host listens on the frame''s window in capture phase (it runs before the framed page''s own Escape, which must win when that page has a panel open). Sierra follows the device when no choice is stored; the library never does, so the host names its theme in ?theme=.', 'A host''s MutationObserver on its data-theme carries a later switch into the frame; the storage event alone does not, because Sierra does not listen for it. In jsdom a frame''s load can fire after the host window closes; wait for the load before window.close() or the handler throws on a null document.', 'When one page shows another inside a panel, keyboard shortcuts and light or dark mode have to be passed across on purpose.', array['sierra','iframe','a11y','pitfall','theme']::text[], array['sierra/sidebar.js','tests/sierra_sidebar.test.js']::text[], 'S469 build and test, 2026-10-24', array['ask-sierra-sidebar-built-2026-10-24']::text[], 'SkyLemonadeBerry-S469', '2026-10-24', 'proposed', null)
on conflict (slug) do nothing;
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select id, 'SkyLemonadeBerry-S469', 'create', 'S469 (2026-10-24)', to_jsonb(m)
from public.cpl_memory m where m.slug in ('sam-ask-sierra-library-first-bottom-right-2026-10-24','ask-sierra-sidebar-built-2026-10-24','pitfall-framed-page-keys-and-theme-2026-10-24')
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');
-- Added ~21:10Z the same run, applied through execute_sql and read back (verified, logged): Sam's word on COBI's Library tab.
insert into public.cpl_memory (slug, kind, org, title, summary, detail, plain, tags, affects, source, related, author, event_date, status, verified_by)
values ('sam-ask-sierra-cobi-library-tab-too-2026-10-24', 'decision', 'cpl', 'Sam: the Ask Sierra chip goes on COBI''s Library tab too, and above all on the public library site', 'Sam, 2026-10-24 ~21:05Z, in S469 after the public library''s side bar was built: "Library and more importantly on the public library site:)" Read as COBI''s Library tab plus the public library page (library/), the public one first in weight.', 'Built the same run: library.js loads sierra/sidebar.js on the tab''s first visit and shows the chip on the Library tab alone (setChip); any other tab hides it and shuts an open bar. The tokens map onto First Light on the bar''s own elements. cpl-project-tracker#2424.', 'Sam wants the Ask Sierra button on the team''s Library tab as well as the public library page.', array['sierra','library','public-library','cobi','sam-ruling']::text[], array['library.js','sierra/sidebar.js']::text[], 'Sam in chat, S469, 2026-10-24 ~21:05Z', array['sam-ask-sierra-library-first-bottom-right-2026-10-24','ask-sierra-sidebar-built-2026-10-24']::text[], 'SkyLemonadeBerry-S469', '2026-10-24', 'verified', 'Sam (his words in chat, 2026-10-24)')
on conflict (slug) do nothing;
